{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Isradipine, a 1,4-dihydropyridine with a lipophilic ester-substituted ring, has a mean systemic availability of 16.5% in healthy volunteers after oral administration, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Pentazocine, which bears a prenyl side chain and a phenolic ring, has an oral bioavailability of 0.18 (18%) in normal subjects, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Nifedipine, a 1,4-dihydropyridine with a similar ester-substituted ring, has an oral bioavailability of about 45% in humans, above the 20% threshold, but its dihydropyridine core and metabolic liability are not present in the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a large, highly lipophilic polyisoprenoid benzoquinone with no ionizable groups and a very long isoprenoid tail, properties associated with poor aqueous solubility and extensive first-pass metabolism. The most transferable experimental analogues (isradipine, pentazocine) show oral bioavailability below 20% in healthy subjects, while the positive nifedipine evidence is structurally less transferable. The prediction is low oral bioavailability at the F >= 20% threshold.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the query or a close ubiquinone-like analogue.",
    "The effect of formulation, dose, and food on the query's oral absorption is unknown.",
    "The query's very high lipophilicity and molecular weight may cause solubility-limited absorption that is not captured by the available analogues."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "moderate",
      "card_ids": ["C35"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "dihydropyridine calcium channel blockers"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C28"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "benzomorphan opioids"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C12"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "dihydropyridine calcium channel blockers"
    }
  ],
  "revision_action": "initial"
}

